/// An item's max stack size (64 for an unknown id).
pub fn max_stack(item: ItemKind) -> i32 {
    usize::try_from(item.id())
        .ok()
        .and_then(|i| MAX_STACK.get(i))
        .map_or(64, |n| i32::from(*n))
}

/// An item's max damage; 0 when it does not wear.
pub fn max_damage(item: ItemKind) -> i32 {
    usize::try_from(item.id())
        .ok()
        .and_then(|i| MAX_DAMAGE.get(i))
        .map_or(0, |n| i32::from(*n))
}

/// The tool an item is, if it is one.
pub fn tool_of(item: ItemKind) -> Option<&'static Tool> {
    TOOLS
        .binary_search_by_key(&item.id(), |t| t.item.id())
        .ok()
        .and_then(|i| TOOLS.get(i))
}
